/// top-k selection into cidx.
fn indexer(e: *const Engine, ch: *Chunk, cs: *const Caches, sh: *Shared, li: usize, wqb: weights.Linear, src: usize, n_comp_end: usize, rope: Rope) !void {
    const lay = e.w.layers[li];
    const c = e.c;
    const n = ch.n;
    const ih = c.index_heads;
    const id = c.index_head_dim;
    if (n_comp_end == 0) { // cidx [n, 0]: no compressed entry yet (a one-token prompt), the attention reads none
        sh.kk = 0;
        return;
    }
    if (n_comp_end > ch.max_comp) return error.ChunkTooLong;
    // 0252: the bypass rides TF_DS_IDX_FUSED, skips the keyed layers (their selection is the kit's _topk_sel, whose
    // order at k == n is not byte-checked against iotaVis) and refuses a config whose pool could coexist with it.
    const pre_keyed = li < c.candidate_source and n_comp_end & (n_comp_end - 1) == 0;
    const pre_nbk = (n_comp_end + c.candidate_block - 1) / c.candidate_block;
    if (e.ops.idx_fused and !pre_keyed and pre_nbk <= c.candidate_blocks and n_comp_end <= c.index_topk) {
        // every compressed key fits in the pick budget: the selection is the visible ids themselves (the k best of
        // n_comp_end keys is all of them, `vis` masking those past the row's count, and the engine's own topk_indices
        // already writes them in ascending column order), so the query projection, its RoPE and quantization, the
        // heads' weights, the scoring and the selection launches are not needed. The decode arm takes the same identity
        // for nb <= index_topk. `pooled` is false here (a pool needs nbk > candidate_blocks), so `sh.pool` stays unset
        // exactly as the full path would leave it.
        try e.ops.iotaVis(e.s, ch.vis, ch.cidx, n_comp_end, n);
        sh.kk = n_comp_end;
        return;
    }
    try mm(e, ch, wqb, ch.qr, lay.wq_a.n, ch.iq, .bf16, ih * id);
    if (fused_trace.queryArm(e.ops.rope_store, n, id, c.rope_dim, ih) != .query_unfused) {
        // TF_DS_FUSED_ROPE_STORE: _rope_heads + _fp4qd_p2 in one launch (the decode arm's kernel: the same Triton
        // arithmetic over the same [rows, heads, head_dim] layout, with the prompt's own positions, ch.pos)
        try e.exact.ropeQd(e.t.stream, ch.iq, ch.iq4, rope.cos, rope.sin, ch.pos, n, ih, id, c.rope_dim);
    } else {
        if (fused_trace.enabled()) fused_trace.note(.query_unfused, n, id, e.ops.pdl);
        try tri_norm.ropeHeads(e.t, ch.iq, rope.cos, rope.sin, ch.pos, c.rope_dim, false, n, ih, id);
        // switch "idx": fp4_qd's bytes in one launch
        try tri_attn.fp4QdP2(e.t, ch.iq, ch.iq4, n * ih * id);
    }
    if (n <= tri.decode_rows) {
        // a decode-sized chunk: the row-invariant matmul of the fp16 projection (rowmm2)
        try tri_norm.rowmm2(e.t, ch.x, c.hidden, lay.idx_proj_h, ch.wl, n, c.hidden, ih);
    } else {
        try e.ops.toF32(e.s, ch.x, ch.xf, n * c.hidden);
        try e.blas.xwT(ch.xf, lay.idx_proj, ch.wl, n, c.hidden, ih);
    }
    try e.exact.bf16Scale(e.s, ch.wl, ch.iw, n * ih, exact.indexScale(id, ih));
    const kk = @min(c.index_topk, n_comp_end);
    // rows in blocks so the [rows, n_comp] keys stay bounded at long contexts, each a multiple of 16 rows
    const rb = indexRowBlock(n, n_comp_end);
    if (rb * n_comp_end > key_elems) return error.ChunkTooLong;
    const keyed = li != c.candidate_source and !(c.candidate_source < li) and kk & (kk - 1) == 0;
    const k: tri_index.IndexK = .{ .fp4 = .{ .codes = cs.idx_codes[src], .scales = cs.idx_scales[src] } };
    const torch_topk: tri_index.TopK = .{ .top = ch.ktop, .ctx = @ptrCast(@constCast(e)), .run = torchTopk };
    if (keyed and tri_index.prunes(n_comp_end, kk) and (rb > pruned_rows or ch.pbufs.cand == 0)) return error.ChunkTooLong;
    // the candidate source and the layers after it: fp32 scores, the pool (_candidates at the source, apply_candidates
    // after it), topk_indices and -1 past vis. While every block of the scores fits in the pool (cand_blocks of them)
    // the pool keeps each block with a finite score (the newest pinned: it holds the row's last visible key) and
    // apply_candidates rewrites only scores already -inf: no launch changes a byte. Past it the source's block maxima
    // (the newest block pinned to +inf) pick the pool's cand_blocks blocks (topk_indices: ties to the lower block), the
    // picked blocks with a finite maximum make the chunk's mask, and the later layers' scores outside it become -inf.
    const cb = c.candidate_block;
    const nbk = (n_comp_end + cb - 1) / cb;
    const pooled = !keyed and nbk > c.candidate_blocks;
    if (pooled and (ch.pool == 0 or nbk > ch.pool_ms)) return error.ChunkTooLong;
    const pk = @min(c.candidate_blocks, nbk);
    // TP2 (idx_split): the prompt_keys layers' row blocks split between the ranks at a block boundary, rank 0 the
    // first blocks (rows [0, h0)), rank 1 the rest (rows [h0, n)), the boundary the one that evens their rows most.
    // Every block keeps the replicated loop's rows, offsets and launches, so each row's selection has the same bits;
    // the gather below gives both ranks every row's.
    const nb = (n + rb - 1) / rb;
    var h0: usize = n;
    for (1..@max(nb, 1)) |s| {
        if (@max(s * rb, n - s * rb) < @max(h0, n - h0)) h0 = s * rb;
    }
    const big = @max(h0, n - h0); // the larger part's rows: the gather's rows a rank
    const ke = @min(ch.cap * ch.max_comp, key_elems);
    const split = idx_split and n_comp_end >= idx_split_min_comp and keyed and e.two == null and e.world == 2 and e.comm.world == 2 and nb >= 2 and 2 * big * kk <= ke;
    const mine: [2]usize = if (!split) .{ 0, n } else if (e.comm.rank == 0) .{ 0, h0 } else .{ h0, n };
    var r0: usize = mine[0];
    while (r0 < mine[1]) : (r0 += rb) {
        // the block's rows: iq[r0:r1] and wts[r0:r1] as views (their offsets the served pointers'), vis[r0:r1] at a
        // 16-byte-aligned address (visBlock), its selection into cidx[r0:r1]
        const m = @min(n, r0 + rb) - r0;
        const q = ch.iq4 + r0 * ih * id * 2;
        const wb = ch.iw + r0 * ih * 2;
        const vr = try visBlock(e, ch, r0, m);
        const out = ch.cidx + r0 * kk * 8;
        if (keyed) {
            try tri_index.indexScore(e.t, q, k, wb, vr, n_comp_end, ch.keys, null, true, ch.tmax, false, m, ih, id);
            try tri_index.topkSelectPruned(e.t, ch.keys, n_comp_end, ch.tmax, kk, vr, out, ch.pbufs, torch_topk, m, n_comp_end);
        } else {
            try tri_index.indexScore(e.t, q, k, wb, vr, n_comp_end, ch.score, null, false, null, false, m, ih, id);
            const mrows = ch.pool + r0 * ch.pool_ms;
            if (pooled and li == c.candidate_source) {
                // TF_DS_IDX_FUSED: the same three launches in one (off by default); the mask keeps its offset (mrows)
                if (fused_trace.idxArm(e.ops.idx_fused, false, m, n_comp_end, cb, nbk, pk) == .idx_fused) {
                    try e.ops.idxFused(e.s, ch.score, n_comp_end, n_comp_end, cb, vr, ch.every, pk, mrows, ch.pool_ms, 0, m);
                } else {
                    if (fused_trace.enabled()) fused_trace.note(.idx_unfused, m, n_comp_end, e.ops.pdl);
                    try e.ops.blockMax(e.s, ch.score, n_comp_end, n_comp_end, cb, vr, ch.bmax, nbk, m);
                    try e.ops.topkIndices(e.s, ch.bmax, nbk, m, nbk, pk, ch.every, ch.pidx);
                    try e.ops.poolPick(e.s, ch.bmax, nbk, nbk, ch.pidx, pk, mrows, ch.pool_ms, 0, m);
                }
            } else if (pooled and c.candidate_source < li) {
                if (!sh.pool) return error.NoCandidatePool;
                try e.ops.applyPool(e.s, ch.score, n_comp_end, n_comp_end, cb, mrows, ch.pool_ms, m);
            }
            try e.ops.topkIndices(e.s, ch.score, n_comp_end, m, n_comp_end, kk, vr, out);
        }
    }
    if (split) {
        // `big` rows a rank into keys [2, big, kk] (free now: the blocks' launches before it on the stream are done
        // with it): rank 0 the rows [0, big) (its own [0, h0) first), rank 1 the rows [n - big, n) (its own [h0, n)
        // last); the rest of each part is the other rank's rows, dropped. Each rank then copies the other's rows into
        // cidx: int64 ids moved, no arithmetic.
        std.debug.assert(0 < h0 and h0 < n and big <= n);
        const row = kk * 8;
        const send = if (e.comm.rank == 0) ch.cidx else ch.cidx + (n - big) * row;
        try e.comm.allGather(send, ch.keys, big * kk, .i64, e.s);
        if (e.comm.rank == 0) {
            try e.ops.copyRows(e.s, ch.keys + (big + h0 + big - n) * row, row, ch.cidx + h0 * row, row, row, n - h0);
        } else {
            try e.ops.copyRows(e.s, ch.keys, row, ch.cidx, row, row, h0);
        }
    }
    if (pooled and li == c.candidate_source) sh.pool = true;
    sh.kk = kk;
}

