pub fn parse(text: ?[]const u8) ?bool { ... same ... }

pub fn fromText(text: ?[]const u8) error{BadPromptPicksOnce}!bool {
    return parse(text) orelse error.BadPromptPicksOnce;
}

// -- host reference -------------------------------------------------------------------------------------------------

/// The padded row stride (sparse_attn's F.pad: whole 16-column tiles).
pub fn padWidth(kk: usize) usize {
    return (kk + 15) / 16 * 16;
}

/// The padded list the attention reads (rows x padWidth(kk) int64): each row its kk picks then -1 in the padding
/// columns (the fill's 0xff bytes). The picks' compact stride stays kk (the sharded fetch reads cidx directly).
pub fn padList(cidx: []const i64, rows: usize, kk: usize, out: []i64) void {
    std.debug.assert(cidx.len >= rows * kk and out.len >= rows * padWidth(kk));
    const kp = padWidth(kk);
    for (0..rows) |r| {
        @memcpy(out[r * kp ..][0..kk], cidx[r * kk ..][0..kk]);
        @memset(out[r * kp + kk ..][0..kp - kk], -1);
    }
}

/// The host-known validity of the padded list: what the previous pad holds, and whether this layer can read it. The
/// validity comes only from the events that change the picks (an indexer's output), the rows (a replay cut) or the
/// chunk (begin), never from comparing device buffers.
pub const Tracker = struct {
    holds: bool = false, // cidxp holds a padded list
    rows: usize = 0,
    kk: usize = 0,

    /// Something changed the picks (an indexer wrote cidx), the rows (a replay cut) or the chunk (begin): the padded
    /// list is stale.
    pub fn stale(t: *Tracker) void {
        t.holds = false;
    }

    /// Whether the padded list made for this rows x kk still holds this layer's picks.
    pub fn reusable(t: *const Tracker, rows: usize, kk: usize) bool {
        return t.holds and t.rows == rows and t.kk == kk;
    }

    /// The padded list now holds rows x kk's picks.
    pub fn held(t: *Tracker, rows: usize, kk: usize) void {
        t.holds = true;
        t.rows = rows;
        t.kk = kk;
    }
};
```

